package com.henson.jarvis;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.speech.RecognizerIntent;import android.speech.tts.*;import android.widget.*;import android.graphics.Color;import java.util.*;
public class MainActivity extends Activity {
 TextToSpeech tts; TextView status; EditText command; boolean ready; Voice selected; LocalBrain brain; boolean loaded; boolean busy; final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,64,32,32);l.setBackgroundColor(0xff101820);setContentView(l);
 TextView title=new TextView(this);title.setText("J A R V I S");title.setTextSize(32);title.setTextColor(0xff63dfff);l.addView(title);
 status=new TextView(this);status.setTextColor(Color.WHITE);status.setTextSize(18);status.setText("Systems ready. Tap to speak.");l.addView(status);
 command=new EditText(this);command.setHint("Enter command");command.setTextColor(Color.WHITE);l.addView(command);
 Button run=new Button(this);run.setText("Execute");l.addView(run);run.setOnClickListener(v->execute(command.getText().toString()));
 Button speak=new Button(this);speak.setText("Speak to JARVIS");l.addView(speak);speak.setOnClickListener(v->{try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-GB");startActivityForResult(i,1);}catch(Exception e){say("Speech recognition is unavailable. Please type your command.");}});
 Button voices=new Button(this);voices.setText("Choose JARVIS voice");l.addView(voices);voices.setOnClickListener(v->chooseVoice());
 Button updates=new Button(this);updates.setText("Check for updates");l.addView(updates);updates.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/seanhenson75-cmyk/Jarvis-/releases/latest/download/JARVIS.apk"))));
 brain=new LocalBrain(getCacheDir().getAbsolutePath());
 Button model=new Button(this);model.setText("Import offline AI model");l.addView(model);model.setOnClickListener(v->{if(busy)return;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,2);});
 Button wifi=new Button(this);wifi.setText("Diagnose Wi-Fi");l.addView(wifi);wifi.setOnClickListener(v->diagnose());
 tts=new TextToSpeech(this,s->{if(s==TextToSpeech.SUCCESS){tts.setLanguage(Locale.UK);tts.setPitch(.85f);tts.setSpeechRate(.92f);ready=true;String saved=getPreferences(0).getString("voice","");for(Voice voice:tts.getVoices()){if(voice.getName().equals(saved)&&tts.setVoice(voice)==TextToSpeech.SUCCESS){selected=voice;break;}}if(selected!=null)say("Systems online, sir.");else status.setText("Choose and preview your preferred British male voice.");}});}
 void say(String s){status.setText(s);if(ready&&selected!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"jarvis");}
 void chooseVoice(){if(!ready)return;ArrayList<Voice> list=new ArrayList<>();for(Voice v:tts.getVoices())if(v.getLocale().getLanguage().equals("en")&&v.getLocale().getCountry().equals("GB")&&!v.isNetworkConnectionRequired())list.add(v);list.sort(Comparator.comparing(Voice::getName));if(list.isEmpty()){status.setText("No offline British voices installed. Open text-to-speech settings to install English UK voice data.");startActivity(new Intent("com.android.settings.TTS_SETTINGS"));return;}String[] names=new String[list.size()];for(int i=0;i<names.length;i++)names[i]=list.get(i).getName();new AlertDialog.Builder(this).setTitle("Preview British voices").setItems(names,(d,i)->{Voice candidate=list.get(i);if(tts.setVoice(candidate)==TextToSpeech.SUCCESS){tts.speak("Systems online, sir. How may I assist?",TextToSpeech.QUEUE_FLUSH,null,"preview");new AlertDialog.Builder(this).setMessage("Keep this voice?").setPositiveButton("Keep",(a,b)->{selected=candidate;getPreferences(0).edit().putString("voice",candidate.getName()).apply();say("Voice saved, sir.");}).setNegativeButton("Try another",(a,b)->{if(selected!=null)tts.setVoice(selected);chooseVoice();}).setOnCancelListener(a->{if(selected!=null)tts.setVoice(selected);}).show();}}).show();}
 void execute(String s){String original=s;s=s.toLowerCase(Locale.ROOT);if(s.contains("wifi")||s.contains("wi-fi")||s.contains("network"))diagnose();else if(s.contains("battery")){Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=b==null?-1:b.getIntExtra("level",-1);say("Battery level: "+level+" percent, sir.");}else if(s.contains("time"))say("The time is "+java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(new Date())+", sir.");else if(s.contains("help"))say("Available commands: Wi-Fi diagnostics, battery level, and time.");else if(loaded&&!busy){busy=true;status.setText("Thinking locally, sir...");worker.execute(()->{try{String answer=brain.ask(original);runOnUiThread(()->{busy=false;say(answer);});}catch(Throwable e){runOnUiThread(()->{busy=false;say("Local AI error: "+e.getMessage());});}});}else say(busy?"Please wait, sir.":"Import an offline AI model first, sir.");}
 void diagnose(){ConnectivityManager cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=cm.getActiveNetwork();NetworkCapabilities c=cm.getNetworkCapabilities(n);if(c==null||!c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)){say("No active Wi-Fi connection detected, sir.");return;}LinkProperties p=cm.getLinkProperties(n);String gateway="unknown";if(p!=null)for(RouteInfo r:p.getRoutes())if(r.isDefaultRoute()&&r.getGateway()!=null){gateway=r.getGateway().getHostAddress();break;}say("Wi-Fi connected, sir. Estimated downstream bandwidth: "+c.getLinkDownstreamBandwidthKbps()/1000+" megabits per second. Gateway: "+gateway+". Internet validation: "+(c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)?"successful":"not confirmed")+". No settings changed.");}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==2&&c==RESULT_OK&&d!=null&&!busy){busy=true;loaded=false;status.setText("Importing and loading model...");Uri uri=d.getData();worker.execute(()->{try{brain.close();java.io.File file=new java.io.File(getFilesDir(),"model.litertlm");try(java.io.InputStream in=getContentResolver().openInputStream(uri);java.io.OutputStream out=new java.io.FileOutputStream(file)){byte[] buf=new byte[1048576];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}brain.load(file.getAbsolutePath());runOnUiThread(()->{loaded=true;busy=false;say("Local intelligence online, sir.");});}catch(Throwable e){runOnUiThread(()->{busy=false;say("Model load failed: "+e.getMessage());});}});return;}if(r==1&&c==RESULT_OK&&d!=null){ArrayList<String>a=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()){command.setText(a.get(0));execute(a.get(0));}}}
 protected void onDestroy(){worker.execute(()->brain.close());worker.shutdown();if(tts!=null)tts.shutdown();super.onDestroy();}
}